SELECT  SUM(courseseq) AS completedNum FROM `yh_user_healthy_plan` WHERE plan_startdate
<=#{planStrTime} AND user_code=#{usercode} AND
plan_unique=#{planUnique}

SELECT ntmp.lianxu_days FROM (SELECT * FROM ( SELECT plan_unique, MAX(days) lianxu_days, MIN(login_day) start_date, MAX(login_day) end_date FROM (SELECT plan_unique, @cont_day := (CASE WHEN (@last_uid = plan_unique AND DATEDIFF(plan_startdate, @last_dt) = 1) THEN (@cont_day + 1) WHEN (@last_uid = plan_unique AND DATEDIFF(plan_startdate, @last_dt) < 1) THEN (@cont_day + 0) ELSE 1 END) AS days, (@cont_ix := (@cont_ix + IF(@cont_day = 1, 1, 0))) AS cont_ix, @last_uid := plan_unique, @last_dt := plan_startdate login_day FROM (SELECT plan_unique, DATE(plan_startdate) plan_startdate FROM yh_user_healthy_plan WHERE plan_unique != 0 AND plan_unique=#{planUnique} AND user_code=#{usercode} ORDER BY plan_unique, plan_startdate) AS t, (SELECT @last_uid := '', @last_dt := '', @cont_ix := 0, @cont_day := 0) AS t1 ) AS t2 GROUP BY plan_unique, cont_ix
) tmp ORDER BY lianxu_days DESC) ntmp
GROUP BY plan_unique

