update yh_user_healthy_plan
user_code = #{userCode}, courseseq = #{courseseq}, plan_day = #{planDay}, plandetail_id = #{plandetailId}, plan_id = #{planId}, plan_startdate = #{planStartdate}, plan_enddate = #{planEnddate}, plan_state = #{planState}, plan_choose = #{planChoose}, plan_unique = #{planUnique},
where id = #{id}
